var calc_output = [];

var age = parseFloat(age);
var ulcersize = parseFloat(ulcersize);
var ulcerlocation = parseFloat(ulcerlocation);

var score = age + ulcersize + ulcerlocation;

var risk = (score < 3) ? 'Low' : 'High';
var recommendation = (score < 3)
  ? 'Follow-up not required if histology is negative'
  : 'Repeat OGD recommended';

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' risk of malignancy'
});

calc_output.push({
    name: '10606_UlcerRisk_result',
    value: score,
    value_text: 'points',
    message: 'Edinburgh Gastric Ulcer Score'
});

calc_output.push({
    name: '10606_UlcerRisk_interpretation',
    value: risk,
    value_text:'risk',
    message: 'Risk of malignancy'
});
